SELECT person_id id FROM resource_use_people WHERE subject_kind=$1 AND subject_id=$2 AND version_id IS NOT DISTINCT FROM $3 AND use_kind=CASE $1 WHEN 'mcp_server' THEN 'mcp_call' WHEN 'skill' THEN 'skill_invocation' WHEN 'host' THEN 'environment_made' WHEN 'template' THEN CASE WHEN EXISTS(SELECT 1 FROM env_templates WHERE id=$2 AND kind='provider') THEN 'provider_made' ELSE 'environment_made' END END AND (NOT $9 OR last_at >= (($6::timestamptz AT TIME ZONE 'UTC')::date-29)::timestamp AT TIME ZONE 'UTC')
